#!/usr/bin/env bash
# Question 3: Worker after a configuration change. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q3_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q3_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q3_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: DaemonSet
metadata:
  name: node-agent
  namespace: ${Q3_NS}
spec:
  selector:
    matchLabels: { app: node-agent }
  template:
    metadata:
      labels: { app: node-agent }
    spec:
      containers:
        - name: agent
          image: registry.k8s.io/pause:3.10
          resources:
            requests: { cpu: 10m, memory: 8Mi }
EOF
kubectl -n "${Q3_NS}" rollout status daemonset/node-agent --timeout=240s

case "${Q3_FAULT}" in
  kubelet-client-ca) ;;
  runtime-endpoint) ;;
  kubelet-config-flag) ;;
  kubelet-kubeconfig-flag) ;;
  kubelet-serving-cert) ;;
  kubelet-eviction-hard) ;;
  kubelet-cgroup-driver) ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
